const ideas = [
{id:'freelance-followup',title:'Freelance Follow-up',category:'Productivity',icon:'↗',level:'Beginner',weeks:2,skills:['JavaScript','CRUD','Date handling'],description:'Help freelancers keep client follow-ups from falling through the cracks.',problem:'Freelancers juggle potential clients across email, notes, and memory. A promising conversation can go quiet simply because nobody remembered to follow up.',users:'Solo freelancers managing a handful of leads while doing paid client work.',scope:['Add a lead with a name, project, and next follow-up date.','See upcoming and overdue follow-ups in one list.','Mark a follow-up complete and set the next step.'],author:'Maya Chen',role:'Freelance designer',initials:'MC'},
{id:'pantry-first',title:'Pantry First',category:'Everyday life',icon:'⌂',level:'Beginner',weeks:2,skills:['JavaScript','Forms','Filtering'],description:'Turn the ingredients already in a kitchen into a plan for the next meal.',problem:'People buy groceries without remembering what they already have. Ingredients expire while meal planning starts from scratch.',users:'Students and roommates cooking on a budget with a small shared pantry.',scope:['Add pantry ingredients and their expiry dates.','Filter a small recipe collection by available ingredients.','Show the missing ingredients for a selected recipe.'],author:'Eli Brooks',role:'Student & home cook',initials:'EB'},
{id:'study-circle',title:'Study Circle',category:'Education',icon:'≡',level:'Intermediate',weeks:4,skills:['React','Database','Scheduling'],description:'Give small study groups one place to agree on what to work on next.',problem:'Study groups lose meeting time sorting through scattered messages about topics, tasks, and availability.',users:'College students meeting weekly to prepare for the same course exams.',scope:['Create a study session with a time and topic.','Add shared preparation tasks and assign an owner.','Track completed topics before the next exam.'],author:'Jordan Lee',role:'Peer tutor',initials:'JL'},
{id:'issue-brief',title:'Issue Brief',category:'Developer tools',icon:'{ }',level:'Intermediate',weeks:4,skills:['React','REST APIs','Markdown'],description:'Turn scattered bug reports into clear, reproducible steps for a small team.',problem:'Small software teams receive bug reports that leave out the context needed to reproduce an issue, leading to repeated clarification.',users:'Student development teams and maintainers of small open-source projects.',scope:['Collect expected behavior, actual behavior, and reproduction steps.','Preview a consistently formatted issue report.','Copy the report as Markdown for a repository issue.'],author:'Sam Rivera',role:'Software developer',initials:'SR'},
{id:'volunteer-slot',title:'Volunteer Slot',category:'Community',icon:'◎',level:'Beginner',weeks:1,skills:['HTML / CSS','JavaScript','Forms'],description:'Help a neighborhood group see which volunteer shifts still need a hand.',problem:'Community organizers manage sign-ups in long message threads and have trouble spotting unfilled shifts.',users:'Volunteer coordinators running small weekend events.',scope:['List event shifts with time and capacity.','Let a volunteer reserve an available spot.','Display remaining openings and allow a cancellation.'],author:'Alex Morgan',role:'Community volunteer',initials:'AM'},
{id:'subscription-check',title:'Subscription Check',category:'Everyday life',icon:'↻',level:'Intermediate',weeks:3,skills:['JavaScript','Charts','Date handling'],description:'Make recurring subscriptions and upcoming renewals easier to understand.',problem:'People sign up for tools and entertainment over time, then lose track of their combined cost and renewal dates.',users:'Young professionals reviewing their monthly spending.',scope:['Manually enter subscriptions, prices, and renewal dates.','Calculate a monthly total from different billing cycles.','Highlight renewals coming in the next two weeks.'],author:'Taylor Kim',role:'Product designer',initials:'TK'}
];
const app=document.querySelector('#app');const saved=new Set();const filters={search:'',category:'All categories',level:'All levels',time:'Any duration'};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'browse_project_ideas',description:'Search the sample project ideas and open the filtered idea board.',inputSchema:{type:'object',properties:{search:{type:'string'}},required:['search'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.search!=='string')throw new Error('search must be a string');filters.search=input.search;filters.category='All categories';filters.level='All levels';filters.time='Any duration';history.replaceState(null,'','#/ideas');render();return {ideas:filtered().map(i=>({id:i.id,title:i.title,level:i.level,weeks:i.weeks}))}}})).catch(()=>{});}catch{}}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(i,featured=false){return `<a class="project-card" href="#/ideas/${i.id}"><div class="card-top"><span class="icon-box" aria-hidden="true">${i.icon}</span><span class="category">${featured?'Featured spark':i.category}</span></div><h3>${i.title}</h3><p>${i.description}</p><div class="tags"><span class="tag yellow">${i.level}</span><span class="tag">${i.weeks} ${i.weeks===1?'week':'weeks'}</span><span class="tag">${i.category}</span></div><div class="card-bottom"><span class="small-label">A real problem. A clear starting point.</span><strong aria-label="View idea">↗</strong></div></a>`}
function home(){app.innerHTML=`<section class="hero"><div><p class="eyebrow">For your next side project</p><h1>You bring the skills.<br>Find your <em>spark.</em></h1><p class="intro">Find a real-world SaaS project that fits your skills and time. A clear idea. A first version you can actually build.</p><a class="button" href="#/ideas">Browse ideas <span aria-hidden="true">↗</span></a><p class="micro">Explore the problem, the scope, and where to start.</p></div><div class="feature-wrap">${card(ideas[0],true)}<p class="feature-note">✦ &nbsp; Your next portfolio project could start here.</p></div></section><section class="principles" aria-label="From idea to direction"><div><span class="step">01 /</span><section><strong>Find a problem worth solving</strong><p>Ideas grounded in everyday needs.</p></section></div><div><span class="step">02 /</span><section><strong>Know what you're taking on</strong><p>Skills, time, and a focused first version.</p></section></div><div><span class="step">03 /</span><section><strong>Make it your own</strong><p>Pick your starting point. Build from there.</p></section></div></section>`}
function select(label,key,values){return `<label>${label}<select data-filter="${key}">${values.map(v=>`<option${filters[key]===v?' selected':''}>${v}</option>`).join('')}</select></label>`}
function browse(){app.innerHTML=`<section class="page-head"><p class="eyebrow">The idea board</p><h1>A spark that fits you.</h1><p>Find an interesting problem with a manageable first step.</p></section><section class="filters" aria-label="Filter project ideas"><label>Search ideas<input type="search" id="search" placeholder="Try productivity or JavaScript" value="${escapeHTML(filters.search)}"></label>${select('Category','category',['All categories',...new Set(ideas.map(i=>i.category))])}${select('Skill level','level',['All levels','Beginner','Intermediate'])}${select('Build time','time',['Any duration','Up to 2 weeks','3–4 weeks'])}</section><div class="results"><span id="count" role="status"></span><button class="text-button" id="clear">Reset filters</button></div><section class="grid" id="results" aria-label="Project ideas"></section>`;document.querySelector('#search').addEventListener('input',e=>{filters.search=e.target.value;results()});document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change',()=>{filters[el.dataset.filter]=el.value;results()}));document.querySelector('#clear').onclick=()=>{Object.assign(filters,{search:'',category:'All categories',level:'All levels',time:'Any duration'});browse()};results()}
function filtered(){return ideas.filter(i=>(i.title+' '+i.description+' '+i.skills.join(' ')).toLowerCase().includes(filters.search.toLowerCase())&&(filters.category==='All categories'||i.category===filters.category)&&(filters.level==='All levels'||i.level===filters.level)&&(filters.time==='Any duration'||(filters.time==='Up to 2 weeks'?i.weeks<=2:i.weeks>=3)))}
function results(){const list=filtered();document.querySelector('#count').textContent=`${list.length} ${list.length===1?'idea':'ideas'} to explore`;document.querySelector('#results').innerHTML=list.length?list.map(i=>card(i)).join(''):'<div class="empty"><h2>No sparks here yet.</h2><p>Try a different search or reset your filters.</p></div>'}
function detail(id){const i=ideas.find(x=>x.id===id);if(!i){app.innerHTML='<section class="page-head"><h1>Idea not found.</h1><a class="button" href="#/ideas">Browse ideas</a></section>';return}app.innerHTML=`<a class="back" href="#/ideas">← Back to ideas</a><section class="detail-heading"><span class="category">${i.category} / Project brief</span><h1>${i.title}<span class="brand-dot">.</span></h1><p>${i.description}</p></section><div class="detail-layout"><div><section class="detail-section"><h2>The problem</h2><p>${i.problem}</p></section><section class="detail-section"><h2>Who you're building for</h2><p>${i.users}</p></section><section class="detail-section"><h2>Your first version</h2><ul class="scope-list">${i.scope.map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="detail-section"><h2>Shared by</h2><div class="person"><span class="avatar">${i.initials}</span><div>${i.author}<small>${i.role} · Sample contributor</small></div></div></section></div><aside class="summary"><h2>Does this spark fit?</h2><div class="fact"><span>Skill level</span>${i.level}</div><div class="fact"><span>Estimated first build</span>${i.weeks} ${i.weeks===1?'week':'weeks'} · 4–6 hours / week</div><div class="fact"><span>Skills to practice</span><div class="tags">${i.skills.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><button class="button" id="save" aria-pressed="${saved.has(id)}">${saved.has(id)?'✓ Idea saved':'✦ Save this idea'}</button><p class="save-status" id="save-status" role="status">${saved.has(id)?'Saved for this visit.':''}</p><p class="micro">A starting scope, not a fixed recipe. Make it your own.</p></aside></div>`;document.querySelector('#save').onclick=()=>{saved.has(id)?saved.delete(id):saved.add(id);const yes=saved.has(id);document.querySelector('#save').textContent=yes?'✓ Idea saved':'✦ Save this idea';document.querySelector('#save').setAttribute('aria-pressed',yes);document.querySelector('#save-status').textContent=yes?'Saved for this visit.':'Idea removed from saved.'}}
function render(){const route=location.hash.slice(1)||'/';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='/'?'home':'ideas');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(route==='/')home();else if(route==='/ideas')browse();else if(route.startsWith('/ideas/'))detail(route.split('/')[2]);else home();document.title=route==='/'?'Sparkbuild — Find your next project':route==='/ideas'?'Browse ideas — Sparkbuild':`${ideas.find(i=>route.endsWith('/'+i.id))?.title||'Idea'} — Sparkbuild`;window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
